-- Quiz AFROBACK : 3 nouveaux mythes de la région du Centre (récits écrits le 2026-10-16)
-- Source : Mythologie/Cameroun/Centre/{slug}/fr.md et en.md (textes identiques à supabase/mythes-centre-nouveaux_2026-10-16.sql). Rédigé par l'agent afroback-quiz.
-- BROUILLON : à relire par Yannick (FR) et par un anglophone (EN) avant exécution.
-- Remplace UNIQUEMENT les questions de ces 3 mythes. Autres quiz et tentatives non touchés.
-- bonne_reponse = index à partir de 0 dans choix_fr (même index dans choix_en).

begin;

delete from public.quiz_questions
where type_contenu = 'mythe'
  and slug in ('mythe-zamba-evu-beti', 'mythe-ngam-araignee-beti', 'mythe-enfants-ombono-mbam');


commit;

-- Contrôle : chaque mythe doit avoir exactement 5 questions.
select slug, count(*) as nb_questions
from public.quiz_questions
where type_contenu = 'mythe'
  and slug in ('mythe-zamba-evu-beti', 'mythe-ngam-araignee-beti', 'mythe-enfants-ombono-mbam')
group by slug
order by slug;
